<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();$page_title='Messages clients';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cid=(int)($_POST['client_id']??0);$msg=trim($_POST['message']??'');$orderId=($_POST['order_id']??'')!==''?(int)$_POST['order_id']:null;if($cid>0&&$msg!==''){db()->prepare("INSERT INTO messages(client_id,order_id,canal,message) VALUES(?,?,?,?)")->execute([$cid,$orderId,'sms',$msg]);flash('Message enregistré dans l’historique. Cliquez sur « Ouvrir les SMS » pour l’envoyer depuis votre téléphone.');}redirect('messages.php');}
$clients=db()->query("SELECT id,nom,prenom,telephone FROM clients ORDER BY nom")->fetchAll();$msgs=db()->query("SELECT m.*,c.nom,c.prenom,c.telephone,o.code FROM messages m JOIN clients c ON c.id=m.client_id LEFT JOIN orders o ON o.id=m.order_id ORDER BY m.id DESC LIMIT 50")->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Envoyer un SMS simple</h2><p class="muted">Aucun WhatsApp. Le message est préparé dans l’application SMS du téléphone connecté/configuré. L’envoi est confirmé depuis le téléphone et peut être facturé par l’opérateur.</p><form method="post" class="form-grid" id="messageForm"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Client</label><select name="client_id" id="clientSelect" required><?php foreach($clients as $c):$phone=preg_replace('/\D/','',$c['telephone']);if(strlen($phone)===9)$phone='237'.$phone;?><option value="<?=$c['id']?>" data-phone="<?=e('+'.$phone)?>"><?=e($c['prenom'].' '.$c['nom'].' · '.$c['telephone'])?></option><?php endforeach;?></select></div><div class="field full"><label>Message</label><textarea name="message" id="messageText" rows="4" required placeholder="Bonjour, votre commande est prête à être retirée. Merci."></textarea></div><div class="field full"><button class="btn">Enregistrer dans l'historique</button> <button type="button" class="btn green" onclick="openSMS()">Ouvrir les SMS</button></div></form></div>
<div class="panel"><h2>Historique récent</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Client</th><th>Canal</th><th>Message</th><th>Commande</th></tr></thead><tbody><?php foreach($msgs as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['created_at']))?></td><td><?=e($m['prenom'].' '.$m['nom'])?></td><td>SMS</td><td><?=e($m['message'])?></td><td><?=e($m['code'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<script>function openSMS(){const s=document.getElementById('clientSelect'),p=s.options[s.selectedIndex]?.dataset.phone,m=document.getElementById('messageText').value.trim();if(!p||!m){alert('Choisissez un client et saisissez un message.');return;}window.location.href='sms:'+p+'?body='+encodeURIComponent(m);}</script>
<?php require 'includes/footer.php';?>
